-- Table: transaction_vendor_payment_detail
-- Source: accounting_admin_db.sql (4. Purchasing flow)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS transaction_vendor_payment_detail (
    id                   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    vendor_payment_id    BIGINT NOT NULL REFERENCES transaction_vendor_payment(id) ON DELETE CASCADE,
    line_number          INTEGER NOT NULL CHECK (line_number > 0),
    purchase_invoice_id  BIGINT NOT NULL REFERENCES transaction_purchase_invoice(id),
    amount               NUMERIC(18,2) NOT NULL CHECK (amount > 0),
    notes                TEXT,
    UNIQUE (vendor_payment_id, line_number)
);
